import jakarta.servlet.http.*;import org.springframework.context.ConfigurableApplicationContext;import org.springframework.web.bind.annotation.RequestMethod;import org.springframework.web.servlet.mvc.method.RequestMappingInfo;import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;import com.baomidou.dynamic.datasource.DynamicRoutingDataSource;
/** Test-only read observer: existing pool, owned synthetic database, no account/session/variable tables. */
public final class OwnWorkflowSnapshot {
 private final ConfigurableApplicationContext context;private final Path root;private final String nonce;
 private OwnWorkflowSnapshot(ConfigurableApplicationContext c){context=c;root=Path.of(System.getProperty("own.fixture.snapshot.root")).toAbsolutePath().normalize();nonce=System.getProperty("own.fixture.snapshot.nonce");if(!root.getParent().equals(Path.of("D:/Project/Zhumadian/work/event_delivery_consistency_20261030"))||!root.getFileName().toString().matches("full-business-main-r[1-9][0-9]*")||nonce==null||!nonce.matches("[a-f0-9]{32}"))throw new IllegalStateException("EXACT_OWN_WORKFLOW_SNAPSHOT_SCOPE");}
 static void register(ConfigurableApplicationContext context){try{var bean=new OwnWorkflowSnapshot(context);var mapping=context.getBean("requestMappingHandlerMapping",RequestMappingHandlerMapping.class);var options=new RequestMappingInfo.BuilderConfiguration();options.setPatternParser(mapping.getPatternParser());var info=RequestMappingInfo.paths("/__own_readonly__/workflow-snapshot").methods(RequestMethod.GET).options(options).build();var method=OwnWorkflowSnapshot.class.getMethod("read",HttpServletRequest.class,HttpServletResponse.class);synchronized(mapping){var current=mapping.getHandlerMethods().get(info);if(current!=null){if(!(current.getBean() instanceof OwnWorkflowSnapshot old)||!old.root.equals(bean.root)||!old.nonce.equals(bean.nonce)||!current.getMethod().equals(method))throw new IllegalStateException("FOREIGN_SNAPSHOT_MAPPING_REFUSED");return;}mapping.registerMapping(info,bean,method);}}catch(Exception e){throw new IllegalStateException("OWN_WORKFLOW_SNAPSHOT_REGISTRATION",e);}}
 @com.cqweh.cloud.security.annotation.IgnoreAuth
 public void read(HttpServletRequest request,HttpServletResponse response)throws Exception{
  if(!"127.0.0.1".equals(request.getRemoteAddr())||!MessageDigest.isEqual(nonce.getBytes(StandardCharsets.US_ASCII),Objects.toString(request.getHeader("X-OWN-READONLY"),"").getBytes(StandardCharsets.US_ASCII))){response.setStatus(403);return;}
  String phase=request.getParameter("phase");if(phase==null||!phase.matches("prepared|submitted|wrong|approved|final|approved-[1-8]")){response.setStatus(400);return;}
  var source=(DynamicRoutingDataSource)context.getBean(javax.sql.DataSource.class);Map<String,Object> tables=new LinkedHashMap<>();
  try(var c=source.getDataSource("tow").getConnection()){boolean prior=c.isReadOnly();try{c.setReadOnly(true);try(var s=c.createStatement()){s.setQueryTimeout(5);try(var r=s.executeQuery("SELECT @@server_uuid,@@port,@@datadir,DATABASE(),@@max_connections")){if(!r.next()||!r.getString(1).equals(System.getProperty("own.expected.database.uuid"))||r.getInt(2)!=Integer.parseInt(System.getProperty("own.expected.database.port"))||!Path.of(r.getString(3)).toRealPath().equals(root.resolve("data").toRealPath())||!"jnpf".equals(r.getString(4))||r.getInt(5)!=24)throw new IllegalStateException("OWN_WORKFLOW_DATABASE_IDENTITY_AND_CAP_REQUIRED");}}
   for(String table:List.of("flow_template","flow_template_json","flow_form_relation","flow_task","flow_task_operator","flow_task_operator_record","act_ru_task","act_hi_procinst","own_approval_form"))tables.put(table,rows(c,"jnpf",table));tables.put("event_task",rows(c,"tj_endanger","event_task"));
  }finally{c.setReadOnly(prior);}}
  response.setStatus(200);response.setContentType("application/json;charset=UTF-8");response.setHeader("Cache-Control","no-store");response.getWriter().write(new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(Map.of("tables",tables,"readOnlyExistingPoolConnection",true,"maxConnections",24,"noAccountSessionOrVariableTablesRead",true,"onlySyntheticOwnedDatabase",true)));
 }
 static String normal(String name){return name.toLowerCase(Locale.ROOT).replace("_","");}
 static List<Map<String,String>> rows(Connection c,String schema,String table)throws Exception{
  Set<String> allowed=Set.of("fid","id","fformid","fflowid","fflowtaskid","ftemplateid","fversionid","fprocessid","fprocessdefinitionid","fdeploymentid","fgroupid","fencode","ffullname","fstatus","fstate","fenabledmark","ftaskid","ftasknodeid","fhandleid","fhandlestatus","fnodecode","fnodename","fcompletion","fcompletiontime","fcreatoruserid","fcreatortime","fhandletime","procinstid","starttime","endtime","startuserid","assignee","name","taskdefkey","createtime","approvalnote","infoid","taskstatus","flowid","taskname","feedbackinfo","disposetime","evaluationsum","dispatchtime","executor","executordept","acceptancedept");List<String> columns=new ArrayList<>();try(var metadata=c.getMetaData().getColumns(schema,null,table,null)){while(metadata.next()){String name=metadata.getString("COLUMN_NAME");if(allowed.contains(normal(name))){if(!name.matches("[A-Za-z_][A-Za-z0-9_]*"))throw new IllegalStateException("CANONICAL_OWN_COLUMN_REQUIRED");columns.add(name);}}}
  if(columns.isEmpty())throw new IllegalStateException("ORIGINAL_WORKFLOW_TABLE_AND_COLUMNS_REQUIRED_"+table);String select=String.join(",",columns.stream().map(n->"`"+n+"`").toList());List<Map<String,String>> out=new ArrayList<>();try(var s=c.createStatement()){s.setQueryTimeout(5);try(var r=s.executeQuery("SELECT "+select+" FROM `"+schema+"`.`"+table+"` LIMIT 11")){while(r.next()){if(out.size()==10)throw new IllegalStateException("BOUNDED_OWN_WORKFLOW_ROWS_REQUIRED");var row=new LinkedHashMap<String,String>();for(int i=0;i<columns.size();i++)row.put(normal(columns.get(i)),r.getString(i+1));out.add(row);}}}return out;
 }
}